func (p *tsdbBasedPlanner) PlanWithFilter(_ context.Context, metasByMinTime []*metadata.Meta, filter func(*metadata.Meta) bool) ([]*metadata.Meta, error) {
	var filtered []*metadata.Meta
	for _, m := range metasByMinTime {
		if filter(m) {
			filtered = append(filtered, m)
		}
	}
	return p.plan(p.noCompBlocksFunc(), filtered)
}

func (t *largeTotalIndexSizeFilter) PlanWithFilter(ctx context.Context, metasByMinTime []*metadata.Meta, filter func(*metadata.Meta) bool) ([]*metadata.Meta, error) {
	var filtered []*metadata.Meta
	for _, m := range metasByMinTime {
		if filter(m) {
			filtered = append(filtered, m)
		}
	}
	return t.plan(ctx, nil, filtered)
}

func (v *verticalCompactionDownsampleFilter) PlanWithFilter(ctx context.Context, metasByMinTime []*metadata.Meta, filter func(*metadata.Meta) bool) ([]*metadata.Meta, error) {
	var filtered []*metadata.Meta
	for _, m := range metasByMinTime {
		if filter(m) {
			filtered = append(filtered, m)
		}
	}
	return v.Plan(ctx, filtered, nil, nil)
}
